\section{Results}
\label{sec:results}
Table~\ref{tab:main} lists the errors and Figure~\ref{fig:curve} the curve; Eq.~\eqref{eq:err} defines $e_{max}$.

\begin{figure}[htbp]
  \centering
  \includegraphics[width=0.6\linewidth]{figs/curve}
  \caption{Training curve.}
  \label{fig:curve}
\end{figure}

\begin{table}[h]
  \centering
  \caption{Errors of both methods.}
  \label{tab:main}
  \begin{tabular}{lccc}
    \toprule
    Method & RMSE & MAE & Time (s) \\
    \midrule
    Baseline & 0.412 & 0.301 & 12.5 \\
    Ours & 0.287 & 0.205 & 14.1 \\
    \bottomrule
  \end{tabular}
\end{table}

